<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">Open dispute</h1><form class="m-card space-y-3" @submit.prevent="submit"><select v-model="form.order_id" required class="m-input"><option value="">Select order</option><option v-for="item in orders" :key="item.id" :value="item.id">{{ item.id.slice(0, 8) }} · {{ item.status }}</option></select><input v-model.trim="form.reason_code" required class="m-input" placeholder="Reason code" /><textarea v-model.trim="form.description" required rows="5" class="m-input" placeholder="Describe the issue" /><button class="m-btn-primary">Open dispute</button></form><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({ middleware: ['auth'] }); const route = useRoute(); const api = useCommerce(); const orders = ref<any[]>([]); const error = ref(''); const form = reactive({ order_id: String(route.query.order_id || ''), reason_code: '', description: '' }); async function submit() { try { await api.createDispute(form.order_id, { reason_code: form.reason_code, description: form.description }); await navigateTo(`/buyer/orders/${form.order_id}`) } catch (e: any) { error.value = e?.data?.detail || e?.message } } onMounted(async () => { orders.value = (await api.listOrders()).items })</script>
